package com.worldgenv2.studio.graph;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * What the engine accepts, as generated by {@code tools/GenNodeSchema.java} from the compiler source.
 * Kinds: density, curve, vector, material, pattern, prop, positions, scanner, assignments, mask, propruntime.
 */
public final class NodeSchemas {
    private NodeSchemas() {}

    public record Param(String key, String type, JsonElement def, String alias) {
        public List<String> enumOptions() {
            return switch (key) {
                case "noiseType" -> List.of("OpenSimplex2", "OpenSimplex2S", "Cellular", "Perlin", "Value");
                case "fractalType" -> List.of("None", "FBm", "Ridged", "PingPong");
                case "cellularDistanceFunction", "distanceFunction" -> List.of("Euclidean", "EuclideanSq", "Manhattan", "Hybrid");
                case "cellularReturnType", "returnType" -> List.of("CellValue", "Distance", "Distance2", "Distance2Add", "Distance2Sub", "Distance2Mul", "Distance2Div", "CellWallDistance");
                default -> List.of();
            };
        }
    }

    public record Slot(String key, String kind, boolean multi, String alias) {}

    public record NodeType(String kind, String name, List<Param> params, List<Slot> slots) {
        public Slot slot(String key) {
            for (Slot s : slots) if (s.key().equals(key) || key.equals(s.alias())) return s;
            return null;
        }
    }

    public static final List<String> KINDS = List.of("density", "curve", "vector", "material", "pattern", "prop",
            "positions", "scanner", "assignments", "mask", "propruntime", "finder", "condition", "action");

    private static Map<String, Map<String, NodeType>> byKind;
    private static final Map<String, String> DOCS = new HashMap<>();

    /** The one-line description a registry gave a parameter (placement pieces), or null. */
    public static String doc(String kind, String type, String key) {
        load();
        return DOCS.get(kind + ":" + type + ":" + key);
    }

    private static synchronized void load() {
        if (byKind != null) return;
        byKind = new LinkedHashMap<>();
        try (InputStream in = NodeSchemas.class.getClassLoader().getResourceAsStream("assets/worldgenv2/node_schema.json")) {
            if (in == null) return;
            JsonObject root = JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
            mergeSchema(root);
        } catch (Exception e) {
            // schema is an aid, not a requirement: the graph still works generically from the JSON
        }
        // Placement pieces come from the live registry, so addon-registered finders/conditions/actions appear automatically.
        try { mergeSchema(com.worldgenv2.placement.Placement.schemaJson()); } catch (Exception ignored) { }
        // Addons ship worldgenv2_node_schemas.json (same format) to add their own node types to the palette.
        try {
            var urls = NodeSchemas.class.getClassLoader().getResources("worldgenv2_node_schemas.json");
            while (urls.hasMoreElements()) {
                try (InputStream in = urls.nextElement().openStream()) {
                    mergeSchema(JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject());
                } catch (Exception ignored) {
                    // one bad addon file must not hide the others
                }
            }
        } catch (Exception ignored) {
        }
        resolveAliases();
    }

    private static void mergeSchema(JsonObject root) {
        for (var kindEntry : root.entrySet()) {
            if (!kindEntry.getValue().isJsonObject()) continue;
            String kind = kindEntry.getKey();
            Map<String, NodeType> types = byKind.computeIfAbsent(kind, k -> new TreeMap<>(String.CASE_INSENSITIVE_ORDER));
            for (var t : kindEntry.getValue().getAsJsonObject().entrySet()) {
                JsonObject o = t.getValue().getAsJsonObject();
                List<Param> params = new ArrayList<>();
                for (JsonElement pe : o.getAsJsonArray("params")) {
                    JsonObject p = pe.getAsJsonObject();
                    if (p.has("doc")) DOCS.put(kind + ":" + t.getKey() + ":" + p.get("key").getAsString(), p.get("doc").getAsString());
                    params.add(new Param(p.get("key").getAsString(), p.get("t").getAsString(),
                            p.has("def") ? p.get("def") : null, p.has("alias") ? p.get("alias").getAsString() : null));
                }
                List<Slot> slots = new ArrayList<>();
                for (JsonElement se : o.getAsJsonArray("slots")) {
                    JsonObject s = se.getAsJsonObject();
                    slots.add(new Slot(s.get("key").getAsString(), s.get("kind").getAsString(), s.get("multi").getAsBoolean(),
                            s.has("alias") ? s.get("alias").getAsString() : null));
                }
                types.put(t.getKey(), new NodeType(kind, t.getKey(), params, slots));
            }
        }
    }

    /** Short names the engine accepts as aliases (Abs for AbsDensity); hidden from palettes, still understood. */
    private static final Set<String> HIDDEN = new HashSet<>();

    /**
     * The engine registers many types twice (X and XDensity). Aliases registered through a different code path
     * come out of the extractor empty, so they borrow the full form's parameters and slots; where both forms
     * are identical the shorter alias is hidden from palettes so each node appears once.
     */
    private static void resolveAliases() {
        for (var kindEntry : byKind.entrySet()) {
            Map<String, NodeType> types = kindEntry.getValue();
            for (String name : new ArrayList<>(types.keySet())) {
                NodeType t = types.get(name);
                for (String suffix : new String[]{"Density", "Curve", "Provider", "Prop", "Pattern", "Scanner"}) {
                    NodeType twin = types.get(name + suffix);
                    if (twin == null) continue;
                    if (t.params().isEmpty() && t.slots().isEmpty() && !(twin.params().isEmpty() && twin.slots().isEmpty())) {
                        types.put(name, new NodeType(t.kind(), t.name(), twin.params(), twin.slots()));
                        t = types.get(name);
                    }
                    if (sameShape(t, twin)) HIDDEN.add(kindEntry.getKey() + ":" + name);
                }
            }
        }
    }

    private static boolean sameShape(NodeType a, NodeType b) {
        if (a.params().size() != b.params().size() || a.slots().size() != b.slots().size()) return false;
        for (int i = 0; i < a.params().size(); i++) if (!a.params().get(i).key().equals(b.params().get(i).key())) return false;
        for (int i = 0; i < a.slots().size(); i++) if (!a.slots().get(i).key().equals(b.slots().get(i).key())) return false;
        return true;
    }

    public static NodeType get(String kind, String type) {
        load();
        Map<String, NodeType> m = byKind.get(kind);
        return m == null ? null : m.get(type);
    }

    /** Finds a type by name in the preferred kind first, then anywhere. */
    public static NodeType find(String preferredKind, String type) {
        NodeType t = get(preferredKind, type);
        if (t != null) return t;
        load();
        for (Map<String, NodeType> m : byKind.values()) {
            NodeType x = m.get(type);
            if (x != null) return x;
        }
        return null;
    }

    public static boolean known(String type) {
        return find("density", type) != null;
    }

    public static List<NodeType> ofKind(String kind) {
        load();
        Map<String, NodeType> m = byKind.get(kind);
        if (m == null) return List.of();
        List<NodeType> out = new ArrayList<>();
        for (NodeType t : m.values()) if (!HIDDEN.contains(kind + ":" + t.name())) out.add(t);
        return out;
    }

    /** A fresh JSON node of the given type with its numeric/bool/string defaults filled in. */
    public static JsonObject newNode(NodeType t) {
        JsonObject o = new JsonObject();
        o.addProperty("type", t.name());
        for (Param p : t.params()) {
            if (p.key().equals("seed")) continue; // seed 0 lets the engine derive a stable salt
            JsonElement d = p.def();
            if (d == null || d.isJsonNull()) continue;
            o.add(p.key(), d.deepCopy());
        }
        for (Slot s : t.slots()) {
            if (s.multi()) o.add(s.key(), new JsonArray());
        }
        return o;
    }

    public static int kindColor(String kind) {
        return switch (kind) {
            case "density" -> 0xFF3E9B4F;
            case "curve" -> 0xFF3A8FD0;
            case "vector" -> 0xFFE08A2B;
            case "material" -> 0xFF9A5BD0;
            case "pattern" -> 0xFFD05B9A;
            case "prop" -> 0xFFD8B820;
            case "positions" -> 0xFF22C0A8;
            case "scanner" -> 0xFF4FB4E8;
            case "assignments" -> 0xFFE8C040;
            case "mask" -> 0xFFE05B7A;
            case "propruntime" -> 0xFFC8A040;
            case "finder" -> 0xFF3FC8B0;
            case "condition" -> 0xFFE0707A;
            case "action" -> 0xFFE8A23C;
            default -> 0xFF8A90A0;
        };
    }
}
